<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/session.php';requireAdmin();$rows=[];$r=$conn->query('SELECT sa.*,u.name,u.email FROM stress_assessments sa LEFT JOIN users u ON sa.user_id=u.id ORDER BY sa.created_at DESC');while($x=$r->fetch_assoc())$rows[]=$x;$c=[0,0,0,0];foreach($rows as $x){$s=(int)$x['stress_level'];$s<=3?$c[0]++:($s<=6?$c[1]++:($s<=8?$c[2]++:$c[3]++));}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Assessments</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="navbar"><a class="logo" href="dashboard.php"><div class="logo-icon">🌿</div><span>Stress<span>Care</span></span></a><div class="nav-links"><a class="nav-btn" href="dashboard.php">Dashboard</a><a class="nav-btn" href="logout.php">Logout</a></div></header><main class="container"><div class="title"><h2>Stress Assessments</h2><p>Review all submitted assessments.</p></div><div class="grid"><div class="stat card"><h3><?=count($rows)?></h3><p>Total</p></div><div class="stat card"><h3><?=$c[0]?></h3><p>Low</p></div><div class="stat card"><h3><?=$c[1]?></h3><p>Moderate</p></div><div class="stat card"><h3><?=$c[2]?></h3><p>High</p></div><div class="stat card"><h3><?=$c[3]?></h3><p>Very High</p></div></div><div class="card" style="margin-top:20px"><div class="table-wrap"><table><tr><th>User</th><th>Stress</th><th>Emotion</th><th>Main Concern</th><th>Sleep</th><th>Category</th><th>Date</th></tr><?php foreach($rows as $x):$s=(int)$x['stress_level'];$cat=$s<=3?'Low':($s<=6?'Moderate':($s<=8?'High':'Very High'));?><tr><td><b><?=htmlspecialchars($x['name']??'Unknown')?></b><br><small><?=htmlspecialchars($x['email']??'')?></small></td><td><b><?=$s?>/10</b></td><td><?=htmlspecialchars($x['emotion']?:$x['mood'])?></td><td><?=htmlspecialchars($x['situation']?:'General Stress')?></td><td><?=$x['sleep_hours']?> hrs</td><td><?=$cat?></td><td><?=date('d M Y, h:i A',strtotime($x['created_at']))?></td></tr><?php endforeach;?></table></div></div></main></body></html>
